contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint sendExactly10, uint sendSmall) public payable {
        require(address(this).balance >= 10 ether);
        require(sendExactly10 == 10 ether);
        require(sendSmall != 10 ether);

        uint before = c.pastBlockTime();

        bool revertedWrongValue;
        try c.fallback{value: sendSmall}() {
            revertedWrongValue = false;
        } catch {
            revertedWrongValue = true;
        }

        bool reverted;
        try c.fallback{value: sendExactly10}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint observed = c.pastBlockTime();

        assert(revertedWrongValue && before == observed && (reverted ? observed == before : observed == block.timestamp + 1));
    }

    receive() external payable {}
}

