contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint timestamp) public payable {
        require(address(this).balance >= 10 ether, "need 10 ether");
        require(amount >= 0, "amount nonnegative");
        require(timestamp > 0, "timestamp must be positive");

        uint pastBefore = c.pastBlockTime();
        uint balBefore = address(c).balance;

        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint pastAfter = c.pastBlockTime();
        uint balAfter = address(c).balance;

        if (reverted) {
            assert(pastAfter == pastBefore && balAfter == balBefore);
        } else {
            assert(pastAfter == block.timestamp + 1);
            assert(pastAfter > pastBefore);
            assert(balAfter == balBefore + 10 ether || balAfter == 0);
            assert(balAfter == 0 ? balBefore + 10 ether > 0 : true);
        }
    }

    receive() external payable {}
}

