        bool reverted;
        (bool success, ) = address(c).call{value: amount}("");
        reverted = !success;

        uint afterTime = c.pastBlockTime();

        assert(
            (reverted && (amount != 10 ether || block.timestamp <= initialTime))
            ||
            (!reverted && amount == 10 ether && block.timestamp > initialTime && afterTime >= block.timestamp)
        );
    }

    receive() external payable {}
}

